import{_ as o,l as N,o as e,c as i,v as t,p as l,x as n,d as p,i as P,S as s}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"GDP、GNI 与 NNP","description":"","frontmatter":{"title":"GDP、GNI 与 NNP","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/gdp-gni-nnp.md","filePath":"econ/gdp-gni-nnp.md","lastUpdated":1789023840000}'),d={name:"econ/gdp-gni-nnp.md"};function G(E,a,h,c,A,D){const r=N("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="gdp、gni-与-nnp" tabindex="-1">GDP、GNI 与 NNP <a class="header-anchor" href="#gdp、gni-与-nnp" aria-label="Permalink to &quot;GDP、GNI 与 NNP&quot;">​</a></h1><div class="epigraph"><p>国内生产钉的是国境上的增加值；国民收入还要问这些增加值最终记在谁的常住单位名下；净额再把固定资本消耗抠掉。</p><footer>—— 据联合国《国民账户体系》（SNA）；Mankiw 宏观教材对 GDP / GNP / NNP 的口径整理</footer></div><p><a href="/econ/gdp-accounts">上一课</a>把三条算法钉在<strong>国内</strong>生产总额 \\(Y\\)。它已经声明：外资企业的境内增加值进 GDP，利润汇出要等到国民口径才扣；折旧决定总额与净额之差，当时用总额、把净额留给后课。本课的缺口就是这两条差：国境对国民，总额对净额。链式物量是下一课；本课仍在名义账户上把名字分清。后课默认：写下 GNI、NNP 时不再把它们与 GDP 混用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三条算法对齐的是常住单位在经济领土上的生产。若要素可以跨境，境内产出不必等于本国居民挣到的初次收入。一家外企在境内的增加值计入 GDP；利润、利息汇出是对国外的初次收入分配，要从国民总收入里扣。本国居民在海外的工资与利润则加回来。缺口不是再问「要不要算福利」，而是：同一套 SNA 边界下，<strong>生产</strong>与<strong>收入</strong>何时分叉。</p><p>总额还含固定资本消耗。机器在生产中被用掉的价值不是新创造的净产品。把折旧留在 \\(Y\\) 里，增长账会把「重置报废设备」写成产出。NNP（或国民净收入）把这一块拿掉。本课一次钉定义，不把开放经济的整本经常账户搬进来。</p><p><span class="marginnote">GNI 旧称 GNP。SNA 强调「收入」而非「产品」：国民总收入是初次分配后的账户，不是把 GDP 换了个国籍形容词。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记对国外的初次收入净额为 \\(NPI\\)（雇员报酬与财产收入的贷方减借方）。则</p> \\[\\mathrm{GNI} \\equiv \\mathrm{GDP} + NPI. \\]<p>再记固定资本消耗为 \\(\\delta K\\) 一类的核算折旧（不是索洛里外生的 \\(\\delta\\) 参数本身）。国民生产净值</p> \\[\\mathrm{NNP} \\equiv \\mathrm{GNI} - \\text{固定资本消耗}. \\]<p>国内一侧也可写 NDP \\(=\\mathrm{GDP}-\\) 固定资本消耗。Mankiw 的教学链是 GDP \\(\\to\\) GNP/GNI \\(\\to\\) NNP \\(\\to\\) 国民收入（再扣间接税等），本课停在前三步：后课储蓄恒等用的仍可以是 GDP 口径的 \\(Y\\)，但谈到「一国居民的收入」必须改口 GNI。</p>',13)),(e(),l(s,null,{default:n(()=>[P(r,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20TD%0A%20%20GDP%5B%22GDP%EF%BC%9A%E5%9B%BD%E5%A2%83%E4%B8%8A%E7%9A%84%E5%A2%9E%E5%8A%A0%E5%80%BC%22%5D%20--%3E%20GNI%5B%22GNI%EF%BC%9A%E5%8A%A0%E8%B7%A8%E5%A2%83%E5%88%9D%E6%AC%A1%E6%94%B6%E5%85%A5%E5%87%80%E9%A2%9D%22%5D%0A%20%20GNI%20--%3E%20NNP%5B%22NNP%EF%BC%9A%E5%86%8D%E5%87%8F%E5%9B%BA%E5%AE%9A%E8%B5%84%E6%9C%AC%E6%B6%88%E8%80%97%22%5D%0A%20%20NNP%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%89%A9%E9%87%8F%E4%B8%8E%E9%93%BE%E5%BC%8F%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>经常转移（侨汇等）还不在 GNI 里，要到国民可支配总收入。完整经常账户在<a href="/econ/open-ca">开放经济会计</a>；本课只把生产与初次收入分开。</p><h3 id="不要把汇出利润写成「gdp-减项」" tabindex="-1">不要把汇出利润写成「GDP 减项」 <a class="header-anchor" href="#不要把汇出利润写成「gdp-减项」" aria-label="Permalink to &quot;不要把汇出利润写成「GDP 减项」&quot;">​</a></h3><p>生产法不因利润汇出而改境内增加值。扣减发生在收入分配账户。把「外企把钱拿走了所以不算产出」，会把生产法与收入法重新打乱——上一课刚对齐的三条路会分叉。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>国境口径问：东西在哪里生产。国民口径问：初次收入记在哪个常住单位。两者在封闭经济重合，一开放就分叉。折旧则是时间上的分叉：总额把重置投资算进产出，净额才接近「还能消费或净积累」的流量。资本形成 \\(I\\) 仍是总额概念（含重置）；与 NNP 对照时要声明用的是总投资还是净投资。</p><p>统计上 \\(NPI\\) 来自国际收支的初次收入，与 GDP 的残差对平不是同一本账。小型开放经济的 GDP 与 GNI 可以差一截：资源出口国的利润若记在外国母公司，GNI 小于 GDP。这是口径，不是「真实国力被低估」的规范判断。</p><p><span class="marginnote">核算折旧按重置成本与资产寿命，不是公司账的加速折旧，更不是索洛 \\(\\delta\\) 的校准值。后课增长模型里的 \\(\\delta\\) 是参数；本课的消耗是 SNA 账户。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 GNI 写成福利，也不把 NNP 当成已经扣掉环境耗损。SNA 的固定资本消耗不包括自然资源耗减与外部成本。持有利得仍是重估价，进出金融资产账户，不进 GDP，也不进 GNI 的生产来源。量化栏的跨境套利与<a href="/quant/irp">利率平价</a>是资产价格，不是 \\(NPI\\) 的定义。</p><p>后课默认：国内生产用 GDP，居民初次收入用 GNI，净产品用 NNP/NDP，三者不再互换。下一课的缺口是：这些名义序列如何变成可加的物量——固定篮子会锁死替代，链式逐年换权。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GDP 钉国境上的生产；GNI 再加跨境初次收入净额。</li><li>NNP 从 GNI 中扣除固定资本消耗；总额与净额不是同一流量。</li><li>利润汇出不改境内增加值，只改国民收入账户。</li><li>经常转移、完整 \\(CA\\) 留给开放账户，本课只分生产与初次收入。</li><li>名义还没有变成增长：物量指数是下一课。</li><li>出处：联合国 SNA；Mankiw 对 GDP、GNP/GNI、NNP 的口径链。</li></ul>',12))])}const I=o(d,[["render",G]]);export{_ as __pageData,I as default};
